<template><view class="page"><view class="title">发布订单</view><view class="card"><view class="field-label">物品信息</view><input class="input" v-model="form.itemName" placeholder="请输入物品信息"/><view class="field-label">备注</view><textarea class="input" v-model="form.remark" placeholder="请输入备注"/><view class="field-label">图片</view><button class="btn secondary" @click="chooseImages">选择图片</button><view class="images"><view v-for="(path,index) in localImages" :key="path" class="image-wrap"><image :src="path" mode="aspectFill" @click="preview(path)"/><view class="remove-image" @click.stop="remove(index)">×</view></view></view><button class="btn" :loading="submitting" @click="submit">发布</button></view></view></template>
<script setup>
import { reactive, ref } from 'vue'; import { api } from '../../utils/request'; import { uploadCloudFile } from '../../utils/cloudStorage';
const form=reactive({itemName:'',remark:'',clientRequestId:''}); const localImages=ref([]); const submitting=ref(false);
async function chooseImages(){const r=await uni.chooseImage({count:6-localImages.value.length,sizeType:['compressed']}); for(const p of r.tempFilePaths)if(!localImages.value.includes(p))localImages.value.push(p)}
function remove(i){localImages.value.splice(i,1)} function preview(path){wx.previewImage({current:path,urls:localImages.value})}
async function submit(){if(submitting.value)return;if(!String(form.itemName||'').trim())return uni.showToast({title:'请填写物品信息',icon:'none'});submitting.value=true;const uploaded=[];let callingApi=false;try{for(const p of localImages.value)uploaded.push((await uploadCloudFile(p,'orders')).fileID);form.clientRequestId=form.clientRequestId||`${Date.now()}-${Math.random().toString(36).slice(2)}`;callingApi=true;const r=await api.createOrder({...form,imageFileIds:uploaded});uni.redirectTo({url:`/pages/order-detail/index?id=${r.orderId}`})}catch(e){if(uploaded.length)wx.cloud.deleteFile({fileList:uploaded});if(!callingApi)uni.showToast({title:'图片上传失败，请稍后重试',icon:'none'})}finally{submitting.value=false}}
</script><style scoped>.field-label{margin:14rpx 0 10rpx;font-size:27rpx;font-weight:600}.images{display:flex;flex-wrap:wrap;gap:14rpx}.image-wrap{position:relative;width:150rpx;height:150rpx}.image-wrap image{width:100%;height:100%;border-radius:6px}.remove-image{position:absolute;right:-8rpx;top:-8rpx;width:38rpx;height:38rpx;line-height:35rpx;text-align:center;border-radius:50%;background:#dc2626;color:#fff;font-size:34rpx}</style>
